def median(values):
    if not isinstance(values, (list, tuple)):
        raise ValueError("values must be a list or tuple")
    if not values:
        return 0
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    if n % 2 == 1:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2

